INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch04$PT127-S1-Q24$batch04$, 127, 1, 24, $batch04$Paradox$batch04$, $batch04$Provinces and states with stringent car safety requirements, including required use of seat belts and annual safety inspections, have on average higher rates of accidents per kilometer driven than do provinces and states with less stringent requirements. Nevertheless, most highway safety experts agree that more stringent requirements do reduce accident rates.$batch04$, $batch04$Which one of the following, if true, most helps to reconcile the safety experts’ belief with the apparently contrary evidence described above?$batch04$, $batch04$C$batch04$, true, $batch04$Batch 04; question text from local bank.$batch04$ FROM lr_sections s WHERE s.preptest=127 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$A$batch04$, $batch04$Annual safety inspections ensure that car tires are replaced before they grow old.$batch04$, $batch04$Half Scope$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$A$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$B$batch04$, $batch04$Drivers often become overconfident after their cars have passed a thorough safety inspection.$batch04$, $batch04$Opposite$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$B$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$C$batch04$, $batch04$The roads in provinces and states with stringent car safety requirements are far more congested and therefore dangerous than in other provinces and states.$batch04$, $batch04$Correct$batch04$, true FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$C$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$D$batch04$, $batch04$Psychological studies show that drivers who regularly wear seat belts often come to think of themselves as serious drivers, which for a few people discourages reckless driving.$batch04$, $batch04$Too Weak$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$D$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch04$E$batch04$, $batch04$Provinces and states with stringent car safety requirements have, on average, many more kilometers of roads than do other provinces and states.$batch04$, $batch04$No Impact$batch04$, false FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch04$E$batch04$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Given that$batch04$, $batch04$Experts agree that stricter car safety requirements reduce accident rates.$batch04$), (1, $batch04$How can it be that$batch04$, $batch04$Places with stricter requirements have higher accident rates per kilometer driven?$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The comparison is between different places, and places differ in more than their rules. If the strict places are more dangerous to begin with, they can have higher accident rates even though the rules are helping.$batch04$), (3, $batch04$Goal$batch04$, $batch04$Find a reason the strict places would have more accidents anyway.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$Newer tires support the experts, but this does not explain why strict places still have more accidents.$batch04$), ($batch04$B$batch04$, $batch04$Overconfidence after inspection is a way the rules could *cause* accidents. That supports the evidence against the experts.$batch04$), ($batch04$C$batch04$, $batch04$The strict places have far more congested, dangerous roads. They would have more accidents without the rules, so the rules can still be lowering a rate that starts higher.$batch04$), ($batch04$D$batch04$, $batch04$Seat belts discouraging reckless driving "for a few people" supports the experts a little, but it does not explain the higher accident rate.$batch04$), ($batch04$E$batch04$, $batch04$The accident rate is per kilometer *driven*. Having more kilometers of road does not change that rate.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT127-S1-Q24$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
